// Horizontal browsing and vertical dragging share one row without treating a swipe as an add.
export function setupObjectStrip({items,strip,board,previous,next,onAdd}){
 let session=null,frame=0,suppressClickUntil=0,lastDetail=null;
 const ghost=document.createElement('div');ghost.className='strip-drag-preview';ghost.hidden=true;ghost.setAttribute('aria-hidden','true');document.body.append(ghost);
 const overBoard=(x,y)=>{const r=board.getBoundingClientRect();return r.width>0&&r.height>0&&x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom};
 function updateButtons(){previous.disabled=strip.scrollLeft<=4;next.disabled=strip.scrollLeft+strip.clientWidth>=strip.scrollWidth-4}
 function browse(direction){strip.scrollBy({left:direction*Math.max(160,strip.clientWidth*.75),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
 previous.onclick=()=>browse(-1);next.onclick=()=>browse(1);strip.addEventListener('scroll',updateButtons,{passive:true});new ResizeObserver(updateButtons).observe(strip);
 function preview(){if(!session||session.mode!=='drag')return;const over=overBoard(session.x,session.y);ghost.style.left=session.x+'px';ghost.style.top=session.y+'px';ghost.dataset.over=String(over);ghost.querySelector('span').textContent=over?'Отпустите на холст':'Перетащите на холст';board.classList.toggle('drop-active',over)}
 function autoScroll(){if(!session||session.mode!=='drag')return;const nav=document.querySelector('.responsive-tools').getBoundingClientRect(),top=Math.max(32,nav.bottom+28),bottom=innerHeight-48;let dy=0;if(session.y<top)dy=-Math.min(16,Math.max(3,(top-session.y)/5));else if(session.y>bottom)dy=Math.min(16,Math.max(3,(session.y-bottom)/5));if(dy)window.scrollBy(0,dy);preview();frame=requestAnimationFrame(autoScroll)}
 function cleanup(){const old=session;session=null;cancelAnimationFrame(frame);ghost.hidden=true;document.body.classList.remove('dragging-object','strip-dragging');board.classList.remove('drop-active');if(old?.card.hasPointerCapture(old.id))old.card.releasePointerCapture(old.id);return old}
 function finish(e,cancelled=false){if(!session||e&&e.pointerId!==session.id)return;const old=session;const point=!cancelled&&old.mode==='drag'&&overBoard(old.x,old.y)?{clientX:old.x,clientY:old.y}:null;if(old.mode!=='pending'||cancelled)suppressClickUntil=performance.now()+400;cleanup();if(point)onAdd(old.key,point)}
 function begin(e,card){if(e.button!==0||!e.isPrimary)return;if(session)cleanup();suppressClickUntil=0;session={id:e.pointerId,card,key:card.dataset.object,startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY,left:strip.scrollLeft,mode:'pending'};card.setPointerCapture(e.pointerId)}
 document.addEventListener('pointermove',e=>{if(!session||e.pointerId!==session.id)return;const s=session;s.x=e.clientX;s.y=e.clientY;const dx=s.x-s.startX,dy=s.y-s.startY;if(s.mode==='pending'){
  if(Math.max(Math.abs(dx),Math.abs(dy))<9)return;
  if(Math.abs(dx)>Math.abs(dy))s.mode='scroll';
  else if(dy<0){s.mode='drag';ghost.replaceChildren();const img=s.card.querySelector('img').cloneNode();img.draggable=false;const label=document.createElement('span');ghost.append(img,label);ghost.hidden=false;document.body.classList.add('dragging-object','strip-dragging');autoScroll()}
  else s.mode='cancelled';
 }
 if(s.mode==='scroll'){if(e.pointerType!=='touch'){e.preventDefault();strip.scrollLeft=s.left-dx}}
 else if(s.mode==='drag'){e.preventDefault();preview()}
 },{passive:false});
 document.addEventListener('pointerup',e=>finish(e));document.addEventListener('pointercancel',e=>finish(e,true));window.addEventListener('blur',()=>finish(null,true));
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&session){e.preventDefault();e.stopPropagation();finish(null,true)}},{capture:true});
 strip.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const cards=[...strip.querySelectorAll('button')],index=cards.indexOf(e.target);if(index<0)return;e.preventDefault();e.stopPropagation();const n=e.key==='Home'?0:e.key==='End'?cards.length-1:Math.max(0,Math.min(cards.length-1,index+(e.key==='ArrowRight'?1:-1)));cards[n].focus({preventScroll:true});cards[n].scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'})});
 return {render(detail){if(detail===lastDetail){updateButtons();return}if(session)cleanup();lastDetail=detail;const left=strip.scrollLeft,focused=document.activeElement?.dataset.focusKey;strip.replaceChildren();for(const item of items){const li=document.createElement('li'),card=document.createElement('button');card.type='button';card.className='strip-object';card.dataset.object=item.key;card.dataset.focusKey=`strip-${item.key}`;card.setAttribute('aria-label',`Добавить на холст: ${item.name}`);card.setAttribute('aria-describedby','object-strip-hint');card.innerHTML=`<img alt="" draggable="false" src="assets/${item.key}-main-${detail}.svg"><span>${item.name}</span><span class="strip-plus" aria-hidden="true"><span class="icon" style="--icon:url('assets/icons/plus.svg')"></span></span>`;card.draggable=false;card.addEventListener('dragstart',e=>e.preventDefault());card.addEventListener('pointerdown',e=>begin(e,card));card.addEventListener('lostpointercapture',e=>{if(session?.id===e.pointerId)finish(e,true)});card.onclick=e=>{if(e.detail!==0&&performance.now()<suppressClickUntil){e.preventDefault();return}onAdd(item.key)};li.append(card);strip.append(li)}strip.scrollLeft=left;if(focused?.startsWith('strip-'))strip.querySelector(`[data-focus-key="${focused}"]`)?.focus({preventScroll:true});requestAnimationFrame(updateButtons)}};
}
